/**
 * @fileoverview Module for the homepage component.
 * This module handles rendering the main page content and includes a navigation button.
 */

// Mock dependencies for a frontend context (assuming a framework like React/Vue/Vanilla JS rendering)
// In a real setup, this would interact with a routing/view layer.

/**
 * Renders the main homepage content.
 * @param {object} props - Component props (e.g., navigation handlers).
 * @returns {string} HTML string representation of the homepage.
 */
const renderHomePage = (props) => {
  console.log("Rendering Homepage...");

  // Function to handle navigation to the 'hello' page
  const handleNavigateToHello = () => {
    if (props.navigateToHello) {
      props.navigateToHello();
    } else {
      console.error("Navigation handler not provided in props.");
      // Fallback: window.location.href = '/hello';
    }
  };

  return `
    <div id="homepage-container" style="padding: 20px; text-align: center;">
      <h1>Welcome to the Application!</h1>
      <p>This is the main landing page.</p>
      <button id="hello-button" onclick="handleNavigationClick()">Go to Hello World Page</button>
      <script>
        // Attach the handler globally or via framework lifecycle
        window.handleNavigationClick = () => { 
          if (window.appContext && window.appContext.navigateToHello) {
            window.appContext.navigateToHello();
          } else {
            console.error("Application context not initialized for navigation.");
          }
        };
      </script>
    </div>
  `;
};

/**
 * Renders the dedicated 'Hello World' page content.
 * @returns {string} HTML string representation of the hello page.
 */
const renderHelloWorldPage = () => {
  console.log("Rendering Hello World Page...");
  return `
    <div id="hello-page-container" style="padding: 20px; text-align: center;">
      <h1>Hello World! 👋</h1>
      <p>This is the dedicated page requested.</p>
      <button onclick="window.router.navigate('/')">Go Back Home</button>
    </div>
  `;
};

// --- Exported Interface ---

/**
 * Entry point to render the appropriate view based on the route.
 * @param {string} route - The current URL path (e.g., '/', '/hello').
 * @param {object} context - Global application context (for navigation hooks).
 * @returns {string} The HTML content to render.
 */
const renderView = (route, context = {}) => {
  try {
    if (route === '/hello') {
      return renderHelloWorldPage();
    } else if (route === '/' || route === '') {
      return renderHomePage({ navigateToHello: context.navigateToHello || (() => console.log('Navigate to Hello called')) });
    } else {
      return `<div>404 Not Found: ${route}</div>`;
    }
  } catch (error) {
    console.error("Error rendering view for route '" + route + "':", error);
    return `<div>Error loading page. Please try again.</div>`;
  }
};

